// StoreWithout drops generated checks by the path each reports under.
//
// For a subject that legitimately violates one. Without this the only recourse
// is to stop running the suite, which costs every other check in the file — so
// a dropped check is reported as skipped rather than silently omitted.
func StoreWithout(paths ...string) StoreOption {
	return func(c *storeConfig) {
		for _, p := range paths {
			c.without[p] = struct{}{}
		}
	}
}

type namedStoreTouchCheck struct {
	name string
	fn   StoreTouchCheck
}

type namedStoreSeenCheck struct {
	name string
	fn   StoreSeenCheck
}

type namedStoreMoveCheck struct {
	name string
	fn   StoreMoveCheck
}

type namedStoreAtCheck struct {
	name string
	fn   StoreAtCheck
}

type namedStoreEmitCheck struct {
	name string
	fn   StoreEmitCheck
}

type namedStoreCountCheck struct {
	name string
	fn   StoreCountCheck
}

type namedStoreSubject struct {
	name    string
	factory func() partnernaming.Store
}

// storeContractExtension is a body of checks a generated sibling adds through an option.
//
// A sibling declares the option and closes over whatever configures it, so
// everything that varies per run is typed and private to the file that owns it
// — this file understands only the name and the call. Nothing arrives except
// through an option, which is what keeps the set fixed before the first subtest
// starts.
type storeContractExtension struct {
	// name is the path this reports under, and the one StoreWithout drops
	// it by. Anything nested beneath it is the extension's own to name.
	name string

	// run takes the factory rather than a subject. One that drives sequences
	// builds a subject per iteration, and one that compares against a reference
	// needs the unseeded subject a factory returns — which
	// storeConfig.subject is not.
	//
	// Called once per subject, in parallel, sharing the config. Anything it
	// mutates has to be built inside the call: state captured when the option
	// was declared is state two subjects write at once.
	run func(
		t *testing.T,
		subject string,
		factory func() partnernaming.Store,
		cfg *storeConfig,
	)
}

type storeConfig struct {
	Fixture  StoreFixture
	subjects []namedStoreSubject
	clock    clock.Clock
	seed     func(ctx context.Context, subject partnernaming.Store) error
	// seedIsDerived is what lets a failed seed name the right culprit. The
	// derived seed and a consumer's are the same field, and the advice for one
	// is useless for the other.
	seedIsDerived bool
	without       map[string]struct{}
	extensions    []storeContractExtension
	onTouch       []namedStoreTouchCheck
	onSeen        []namedStoreSeenCheck
	onMove        []namedStoreMoveCheck
	onAt          []namedStoreAtCheck
	onEmit        []namedStoreEmitCheck
	onCount       []namedStoreCountCheck
}

func newStoreConfig(opts ...StoreOption) *storeConfig {
	c := &storeConfig{
		Fixture: DefaultStoreFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	// Derived: Touch is classified writer, so the interface
	// populates itself and a reader has something to read.
	c.seed = func(ctx context.Context, subject partnernaming.Store) error {
		return subject.Touch(ctx, c.Fixture.Key, c.Fixture.Weight)
	}
	c.seedIsDerived = true
	for _, o := range opts {
		o(c)
	}
	return c
}

// subject builds a fresh implementation and seeds it, so every check runs
// against state no other check touched.
func (c *storeConfig) subject(
	tb testing.TB,
	factory func() partnernaming.Store,
	wrap func(tb testing.TB, subject partnernaming.Store) partnernaming.Store,
) partnernaming.Store {
	tb.Helper()
	s := factory()
	if c.seed != nil {
		// Reported rather than ignored. A seed that silently failed would leave
		// every check after it running against an empty subject — passing, and
		// asserting nothing.
		//
		// Which seed ran decides what the message can usefully say. The derived
		// one fails for one of two reasons and both are fixable from here, so it
		// names them. A seed the caller supplied is theirs, and telling them to
		// supply one is advice they already took.
		if err := c.seed(tb.Context(), s); err != nil {
			if c.seedIsDerived {
				tb.Fatalf("seeding through Touch failed: %v; "+
					"supply a value it accepts through StoreWithFixture, or a "+
					"whole seed through StoreSeed", err)
			} else {
				tb.Fatalf("the seed supplied through StoreSeed failed: %v", err)
			}
		}
	}
	if wrap != nil {
		s = wrap(tb, s)
	}
	return s
}

// dropped reports whether a path was declined through StoreWithout.
//
// Named rather than inlined because the drop set is read from two places: here,
// and by whatever registered through the seam — which reports under paths this
// file has never heard of and must answer the same question about them.
func (c *storeConfig) declined(path string) bool {
	_, ok := c.without[path]
	return ok
}

// storePaths is every path this file reports a check under.
//
// The set a StoreWithout argument has to be a member of. Declared
// rather than observed: a check that did not run is not a check that does not
// exist — an integration-only method skips without ever consulting the drop
// set, and reading that as a phantom would fail a correct suite on a machine
// with the environment unset.
//
//nolint:gochecknoglobals // the emitted check paths, read-only after init.
var storePaths = map[string]struct{}{}

// phantoms names every StoreWithout path that declines nothing.
//
// A drop that drops nothing is this option's silent half: the consumer wrote
// it against a check since renamed, or never emitted for that method at all,
// and every run after reads green while asserting one thing more than its
// author believes. Extensions carry their own names — the seam reports under
// paths this file has never heard of — so they count as known too.
func (c *storeConfig) phantoms() []string {
	known := func(p string) bool {
		if _, ok := storePaths[p]; ok {
			return true
		}
		for _, e := range c.extensions {
			if e.name == p {
				return true
			}
		}
		for _, on := range c.onTouch {
			if string(suite.MethodID(storeTouch, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onSeen {
			if string(suite.MethodID(storeSeen, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onMove {
			if string(suite.MethodID(storeMove, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onAt {
			if string(suite.MethodID(storeAt, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onEmit {
			if string(suite.MethodID(storeEmit, on.name)) == p {
				return true
			}
		}
		for _, on := range c.onCount {
			if string(suite.MethodID(storeCount, on.name)) == p {
				return true
			}
		}
		return false
	}
	var out []string
	for p := range c.without {
		if !known(p) {
			out = append(out, p)
		}
	}
	slices.Sort(out)
	return out
}

// run executes one check unless it was dropped, reporting the drop rather than
// silently omitting it.
func (c *storeConfig) run(t *testing.T, path, name string, fn func(tb testing.TB)) {
	t.Helper()
	if c.declined(path) {
		t.Run(name, func(t *testing.T) {
			t.Skipf("dropped through StoreWithout(%q)", path)
		})
		return
	}
	t.Run(name, func(t *testing.T) {
		t.Parallel()
		fn(t)
	})
}

